import { useMemo, useState, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { AreaChart, Area, BarChart, Bar, CartesianGrid, Cell, PieChart, Pie, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { ArrowRight, BarChart3, Bell, BookOpen, BriefcaseBusiness, Building2, Check, ChevronDown, ChevronRight, CircleAlert, CircleCheck, Clock3, Compass, Filter, GraduationCap, LayoutDashboard, Lightbulb, LineChart, ListChecks, Menu, Plus, Search, Send, Settings, Sparkles, Target, TrendingUp, UserRound, Users, X } from 'lucide-react';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import { currentStudent, students, opportunities, applications as seedApplications, departments, modules, candidates, companyNames } from '@/data/types';
