import '@/index.css';

const queryClient = new QueryClient();

type Toast = { message: string; tone?: 'success' | 'info' };
type DemoContextValue = { applications: Application[]; apply: (id: string) => void; toast: (message: string, tone?: Toast['tone']) => void };
const DemoContext = ({ children, value }: { children: ReactNode; value: DemoContextValue }) => <DemoProvider value={value}>{children}</DemoProvider>;
import { createContext, useContext } from 'react';
const DemoContextStore = createContext<DemoContextValue | null>(null);
function DemoProvider({ children, value }: { children: ReactNode; value: DemoContextValue }) { return <DemoContextStore.Provider value={value}>{children}</DemoContextStore.Provider>; }
function useDemo() { const value = useContext(DemoContextStore); if (!value) throw new Error('Demo context missing'); return value; }

const IconBox = ({ children, className = '' }: { children: ReactNode; className?: string }) => <span className={`grid size-9 place-items-center rounded-xl ${className}`}>{children}</span>;
const Button = ({ children, variant = 'primary', className = '', onClick, type = 'button', disabled = false }: { children: ReactNode; variant?: 'primary' | 'soft' | 'ghost' | 'outline' | 'danger'; className?: string; onClick?: () => void; type?: 'button' | 'submit'; disabled?: boolean }) => <button type={type} disabled={disabled} onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all duration-200 active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${variant === 'primary' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] hover:brightness-110' : variant === 'soft' ? 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))] hover:bg-[hsl(var(--border))]' : variant === 'outline' ? 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] text-[hsl(var(--foreground))] hover:border-[hsl(var(--primary))]' : variant === 'danger' ? 'bg-red-50 text-red-700 hover:bg-red-100' : 'text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]'} ${className}`}>{children}</button>;
const Badge = ({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'teal' | 'orange' | 'green' | 'red' }) => <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold tracking-wide ${tone === 'teal' ? 'bg-teal-100 text-teal-800' : tone === 'orange' ? 'bg-orange-100 text-orange-800' : tone === 'green' ? 'bg-emerald-100 text-emerald-800' : tone === 'red' ? 'bg-red-100 text-red-800' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`}>{children}</span>;
const Card = ({ children, className = '' }: { children: ReactNode; className?: string }) => <section className={`rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] shadow-[0_4px_18px_rgba(26,45,48,.035)] ${className}`}>{children}</section>;
const SectionHeading = ({ eyebrow, title, detail, action }: { eyebrow?: string; title: string; detail?: string; action?: ReactNode }) => <div className="mb-5 flex items-end justify-between gap-4"><div><p className="mono mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-[hsl(var(--primary))]">{eyebrow}</p><h2 className="display text-xl font-extrabold tracking-tight md:text-2xl">{title}</h2>{detail && <p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{detail}</p>}</div>{action}</div>;
const Progress = ({ value, color = 'bg-[hsl(var(--primary))]' }: { value: number; color?: string }) => <div className="h-2 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className={`bar-fill h-full rounded-full ${color}`} style={{ width: `${value}%` }} /></div>;
const Avatar = ({ initials, size = 'md' }: { initials: string; size?: 'sm' | 'md' | 'lg' }) => <div className={`grid shrink-0 place-items-center rounded-full bg-[#d4e8df] font-bold text-[#1b665e] ${size === 'lg' ? 'size-14 text-lg' : size === 'sm' ? 'size-8 text-[11px]' : 'size-10 text-xs'}`}>{initials}</div>;

function Landing() {
  const [, setLocation] = useLocation();
  return <div className="noise min-h-[100dvh] overflow-hidden bg-[#f7f4ec]">
    <nav className="mx-auto flex max-w-7xl items-center justify-between px-5 py-6 md:px-8">
      <Link href="/" className="flex items-center gap-2.5"><span className="grid size-9 place-items-center rounded-xl bg-[#153f43] text-[#f8c27b]"><Sparkles size={18} /></span><span className="display text-xl font-extrabold tracking-tight">skill<span className="text-[#e98250]">bridge</span></span></Link>
      <div className="hidden items-center gap-8 text-sm font-semibold text-[#617174] md:flex"><a href="#how">How it works</a><a href="#roles">For your role</a><a href="#impact">Impact</a></div>
      <Button variant="outline" onClick={() => setLocation('/app/student/dashboard')}>Open demo <ArrowRight size={15} /></Button>
    </nav>
    <main>
      <section className="mx-auto grid max-w-7xl items-center gap-12 px-5 pb-24 pt-12 md:grid-cols-[1.08fr_.92fr] md:px-8 md:pb-36 md:pt-24">
        <div className="fade-up"><Badge tone="orange">COMPETENCY INTELLIGENCE FOR INDIA</Badge><h1 className="display mt-6 max-w-3xl text-5xl font-extrabold leading-[.98] tracking-[-.045em] text-[#153f43] md:text-7xl">Turn what you know into <span className="text-[#e98250]">where you’re going.</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-[#617174]">SkillBridge connects the skills students are building, the gaps worth closing, and the opportunities that are actually within reach.</p><div className="mt-9 flex flex-wrap gap-3"><Button onClick={() => setLocation('/app/student/dashboard')}>See your career signal <ArrowRight size={16} /></Button><Button variant="soft" onClick={() => setLocation('/app/university/dashboard')}>Explore admin view</Button></div><div className="mt-10 flex items-center gap-6 text-sm text-[#617174]"><span className="flex items-center gap-2"><Check size={16} className="text-[#16877b]" /> Built for Indian campuses</span><span className="flex items-center gap-2"><Check size={16} className="text-[#16877b]" /> Explainable by design</span></div></div>
        <div className="fade-up-2 relative mx-auto w-full max-w-[500px]"><div className="absolute -right-8 -top-8 size-48 rounded-full bg-[#f5c879]/35 blur-2xl" /><div className="relative overflow-hidden rounded-[2rem] border border-[#c7d7cc] bg-[#e7f0e8] p-4 shadow-[0_20px_60px_rgba(34,78,72,.12)]"><div className="rounded-[1.5rem] bg-[#153f43] p-5 text-[#f7f4ec]"><div className="flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.2em] text-[#9cc6b7]">Your readiness signal</p><p className="mt-2 text-3xl font-bold">72<span className="text-lg text-[#9cc6b7]">/100</span></p></div><div className="grid size-16 place-items-center rounded-full border-[7px] border-[#f5c879] border-r-[#4c7770] text-sm font-bold">72%</div></div><div className="mt-7 space-y-4">{[['Technical signal','84%','#f5c879'],['Proof of work','68%','#82c8b2'],['Career context','61%','#e98250']].map(([label,value,color]) => <div key={label}><div className="mb-2 flex justify-between text-xs"><span className="text-[#c4d8d2]">{label}</span><span>{value}</span></div><div className="h-1.5 rounded-full bg-[#35615f]"><div className="h-full rounded-full" style={{ width: value, background: color }} /></div></div>)}</div></div><div className="mt-3 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-[#f7f4ec] p-4"><p className="text-xs text-[#617174]">Strongest signal</p><p className="mt-2 font-bold text-[#153f43]">Python</p><p className="mt-1 text-xs text-[#16877b]">+12 this month</p></div><div className="rounded-2xl bg-[#f7f4ec] p-4"><p className="text-xs text-[#617174]">Best next move</p><p className="mt-2 font-bold text-[#153f43]">Product analytics</p><p className="mt-1 text-xs text-[#e98250]">3 skills to close</p></div></div></div><div className="absolute -bottom-5 -left-8 rounded-2xl border border-[#d8e5da] bg-[#fffdf8] px-4 py-3 shadow-xl"><div className="flex items-center gap-3"><span className="grid size-8 place-items-center rounded-full bg-[#fce0ce] text-[#c85e2b]"><Target size={15} /></span><div><p className="text-[11px] text-[#617174]">New match found</p><p className="text-sm font-bold text-[#153f43]">Razorpay · 91%</p></div></div></div></div>
      </section>
      <section className="border-y border-[#e1ddd1] bg-[#efebe1] px-5 py-10 md:px-8"><div className="mx-auto grid max-w-7xl grid-cols-2 gap-8 md:grid-cols-4"><div><p className="display text-3xl font-extrabold text-[#153f43]">20k<span className="text-[#e98250]">+</span></p><p className="mt-1 text-sm text-[#617174]">skills made visible</p></div><div><p className="display text-3xl font-extrabold text-[#153f43]">4.2k</p><p className="mt-1 text-sm text-[#617174]">opportunities mapped</p></div><div><p className="display text-3xl font-extrabold text-[#153f43]">38<span className="text-[#e98250]">%</span></p><p className="mt-1 text-sm text-[#617174]">faster role discovery</p></div><div><p className="display text-3xl font-extrabold text-[#153f43]">12</p><p className="mt-1 text-sm text-[#617174]">campuses in pilot</p></div></div></section>
      <section id="how" className="mx-auto max-w-7xl px-5 py-24 md:px-8"><div className="max-w-2xl"><Badge>FROM SIGNAL TO MOMENTUM</Badge><h2 className="display mt-5 text-4xl font-extrabold tracking-tight text-[#153f43] md:text-5xl">The missing layer between a resume and a real next step.</h2></div><div className="mt-14 grid gap-5 md:grid-cols-3">{[['01','See the signal','Pull skills from coursework, projects, credentials, and experience into one living profile.'],['02','Name the gap','Compare your current signal to the roles you care about — with the why, not just a score.'],['03','Move with proof','Get a sequence of learning, projects, and opportunities that turns intent into evidence.']].map(([n,t,d], i) => <div key={n} className={`rounded-3xl p-7 ${i === 1 ? 'bg-[#153f43] text-[#f7f4ec]' : 'bg-[#e7f0e8] text-[#153f43]'}`}><span className={`mono text-xs ${i === 1 ? 'text-[#f5c879]' : 'text-[#e98250]'}`}>{n}</span><h3 className="display mt-16 text-2xl font-bold">{t}</h3><p className={`mt-3 leading-7 ${i === 1 ? 'text-[#bdd3c9]' : 'text-[#617174]'}`}>{d}</p><ArrowRight className="mt-9" size={20} /></div>)}</div></section>
      <section id="roles" className="bg-[#153f43] px-5 py-24 text-[#f7f4ec] md:px-8"><div className="mx-auto max-w-7xl"><div className="flex flex-col justify-between gap-6 md:flex-row md:items-end"><div><Badge tone="orange">ONE SYSTEM, THREE VIEWS</Badge><h2 className="display mt-5 text-4xl font-extrabold tracking-tight md:text-5xl">Clarity looks different from every seat.</h2></div><p className="max-w-sm leading-7 text-[#b6cec5]">Shared intelligence, tuned to the decisions students, universities, and employers make every day.</p></div><div className="mt-14 grid gap-6 md:grid-cols-3">{[['Students','Know your signal. Choose your next move.','Profile → Gap → Roadmap → Opportunity', '/app/student/dashboard'],['University teams','See readiness before placement season.','Cohorts → Gaps → Interventions', '/app/university/dashboard'],['Recruiters','Find potential, not just keywords.','Brief → Rank → Explain → Connect', '/app/recruiter/dashboard']].map(([t,d,flow,href], i) => <Link href={href} key={t} className="group rounded-3xl border border-[#3c6462] bg-[#204c4f] p-6 transition-transform hover:-translate-y-1"><div className="flex justify-between"><IconBox className={i === 1 ? 'bg-[#f5c879] text-[#153f43]' : 'bg-[#e98250] text-[#153f43]'}>{i === 0 ? <UserRound size={17} /> : i === 1 ? <Building2 size={17} /> : <BriefcaseBusiness size={17} />}</IconBox><ArrowRight className="text-[#9cc6b7] transition-transform group-hover:translate-x-1" /></div><h3 className="display mt-14 text-2xl font-bold">{t}</h3><p className="mt-3 text-[#b6cec5]">{d}</p><p className="mono mt-8 text-[10px] uppercase tracking-[.16em] text-[#f5c879]">{flow}</p></Link>)}</div></div></section>
      <section id="impact" className="mx-auto max-w-7xl px-5 py-24 md:px-8"><div className="grid items-center gap-12 md:grid-cols-[.85fr_1.15fr]"><div><Badge tone="teal">WHY IT MATTERS</Badge><h2 className="display mt-5 text-4xl font-extrabold tracking-tight text-[#153f43] md:text-5xl">Potential is evenly distributed. Signals are not.</h2><p className="mt-6 leading-8 text-[#617174]">SkillBridge gives every learner a legible way to talk about what they can do — and gives the people supporting them a better way to help.</p><Button className="mt-8" onClick={() => setLocation('/app/student/dashboard')}>Walk through the student demo <ArrowRight size={15} /></Button></div><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-3xl bg-[#e7f0e8] p-7"><TrendingUp className="text-[#16877b]" /><p className="mt-10 text-4xl font-extrabold text-[#153f43]">+26 pts</p><p className="mt-2 text-sm text-[#617174]">average readiness lift after a guided learning sprint</p></div><div className="rounded-3xl bg-[#fce0ce] p-7"><Compass className="text-[#c85e2b]" /><p className="mt-10 text-4xl font-extrabold text-[#153f43]">3.4×</p><p className="mt-2 text-sm text-[#617174]">more relevant opportunities surfaced per student</p></div></div></div></section>
      <section className="mx-5 mb-10 rounded-[2rem] bg-[#e98250] px-7 py-14 text-[#153f43] md:mx-auto md:max-w-7xl md:px-16"><div className="flex flex-col justify-between gap-8 md:flex-row md:items-center"><div><p className="mono text-[10px] font-bold uppercase tracking-[.2em]">START WITH ONE PROFILE</p><h2 className="display mt-4 max-w-2xl text-4xl font-extrabold tracking-tight md:text-5xl">Make the next step feel possible.</h2></div><Button variant="outline" className="border-[#153f43] bg-transparent" onClick={() => setLocation('/app/student/dashboard')}>Enter SkillBridge <ArrowRight size={15} /></Button></div></section>
    </main>
    <footer className="mx-auto flex max-w-7xl justify-between px-5 py-8 text-sm text-[#617174] md:px-8"><span className="display font-bold text-[#153f43]">skillbridge</span><span>Competency intelligence, built in India.</span></footer>
  </div>;
}

const studentNav = [{ href: '/app/student/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/app/student/profile', label: 'My profile', icon: UserRound }, { href: '/app/student/skill-gap', label: 'Skill gap', icon: Target }, { href: '/app/student/learning', label: 'Learning plan', icon: BookOpen }, { href: '/app/student/opportunities', label: 'Opportunities', icon: BriefcaseBusiness }, { href: '/app/student/applications', label: 'Applications', icon: ListChecks }];
const universityNav = [{ href: '/app/university/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/app/university/skills', label: 'Skill intelligence', icon: BarChart3 }, { href: '/app/university/departments', label: 'Departments', icon: Building2 }, { href: '/app/university/demand', label: 'Demand vs supply', icon: LineChart }, { href: '/app/university/training', label: 'Training priorities', icon: Lightbulb }];
const recruiterNav = [{ href: '/app/recruiter/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/app/recruiter/create', label: 'Create opportunity', icon: Plus }, { href: '/app/recruiter/opportunities', label: 'My opportunities', icon: BriefcaseBusiness }, { href: '/app/recruiter/candidates', label: 'Candidate pool', icon: Users }];

function AppShell({ children, role }: { children: ReactNode; role: 'student' | 'university' | 'recruiter' }) {
  const [location, setLocation] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const nav = role === 'student' ? studentNav : role === 'university' ? universityNav : recruiterNav;
  const roleName = role === 'student' ? 'Student workspace' : role === 'university' ? 'University intelligence' : 'Recruiter workspace';
  return <div className="min-h-[100dvh] bg-[#f7f4ec] text-[#153f43]"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[260px] flex-col border-r border-[#dce5dc] bg-[#e8f0e8] p-5 transition-transform md:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between"><Link href="/" className="flex items-center gap-2"><span className="grid size-8 place-items-center rounded-lg bg-[#153f43] text-[#f8c27b]"><Sparkles size={16} /></span><span className="display text-lg font-extrabold">skill<span className="text-[#e98250]">bridge</span></span></Link><button className="md:hidden" onClick={() => setMobileOpen(false)}><X size={18} /></button></div><div className="mt-8 rounded-2xl border border-[#cfdfd2] bg-[#f7f4ec]/70 p-3"><p className="mono text-[9px] uppercase tracking-[.18em] text-[#6e8580]">Signed in as</p><div className="mt-3 flex items-center gap-3"><Avatar initials={role === 'student' ? 'AI' : role === 'university' ? 'NC' : 'SD'} size="sm" /><div className="min-w-0"><p className="truncate text-sm font-bold">{role === 'student' ? 'Ananya Iyer' : role === 'university' ? 'Nandita Chawla' : 'Sahil Deshpande'}</p><p className="truncate text-[11px] text-[#6e8580]">{roleName}</p></div></div></div><p className="mono mb-2 mt-9 px-3 text-[9px] font-bold uppercase tracking-[.18em] text-[#7b918d]">Workspace</p><nav className="space-y-1">{nav.map((item) => { const Icon = item.icon; const active = location === item.href; return <Link onClick={() => setMobileOpen(false)} key={item.href} href={item.href} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition-colors ${active ? 'bg-[#153f43] text-[#f7f4ec]' : 'text-[#52706d] hover:bg-[#dce8de]'}`}><Icon size={17} /><span>{item.label}</span>{item.label === 'Applications' && <span className="ml-auto rounded-full bg-[#e98250] px-1.5 text-[10px] text-[#153f43]">3</span>}</Link>})}</nav><div className="mt-auto rounded-2xl bg-[#153f43] p-4 text-[#d5e6df]"><p className="mono text-[9px] uppercase tracking-[.16em] text-[#f5c879]">Signal tip</p><p className="mt-3 text-sm leading-5">A project with a measurable outcome lifts your profile more than another certificate.</p><Link href="/app/student/profile" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-[#f5c879]">Improve profile <ArrowRight size={13} /></Link></div></aside><div className="md:pl-[260px]"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-[#e4e0d5] bg-[#f7f4ec]/90 px-5 backdrop-blur-md md:px-9"><button className="rounded-lg p-2 hover:bg-[#e9e5da] md:hidden" onClick={() => setMobileOpen(true)}><Menu size={20} /></button><div className="hidden text-sm font-semibold text-[#6e8580] md:block">{roleName} <span className="mx-2 text-[#bcc8bf]">/</span> <span className="text-[#153f43]">October 2025</span></div><div className="ml-auto flex items-center gap-3"><RoleSwitcher role={role} /><button className="relative rounded-xl p-2 text-[#6e8580] hover:bg-[#e9e5da]"><Bell size={18} /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-[#e98250]" /></button><Avatar initials={role === 'student' ? 'AI' : role === 'university' ? 'NC' : 'SD'} size="sm" /></div></header><main className="mx-auto max-w-[1440px] p-5 md:p-9">{children}</main></div></div>;
}

function RoleSwitcher({ role }: { role: string }) { const [, setLocation] = useLocation(); return <select value={role} onChange={(e) => setLocation(`/app/${e.target.value}/dashboard`)} className="rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-3 py-2 text-xs font-bold text-[#153f43] outline-none"><option value="student">Student view</option><option value="university">University view</option><option value="recruiter">Recruiter view</option></select>; }

function PageIntro({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) { return <div className="fade-up mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mono text-[10px] font-bold uppercase tracking-[.2em] text-[#16877b]">{eyebrow}</p><h1 className="display mt-2 text-3xl font-extrabold tracking-tight md:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#6e8580]">{detail}</p></div>{action}</div>; }
const Metric = ({ label, value, detail, icon: Icon, accent = 'teal' }: { label: string; value: string; detail: string; icon: typeof TrendingUp; accent?: 'teal' | 'orange' | 'yellow' }) => <Card className="p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-[#6e8580]">{label}</p><p className="display mt-2 text-3xl font-extrabold tracking-tight">{value}</p></div><IconBox className={accent === 'orange' ? 'bg-[#fce0ce] text-[#c85e2b]' : accent === 'yellow' ? 'bg-[#f8edc9] text-[#aa7b18]' : 'bg-[#d9eee7] text-[#16877b]'}><Icon size={17} /></IconBox></div><p className="mt-4 text-xs text-[#6e8580]">{detail}</p></Card>;

function StudentDashboard() { const [, setLocation] = useLocation(); const { applications } = useDemo(); return <><PageIntro eyebrow="Student overview" title={`Good morning, Ananya.`} detail="Your profile is gaining signal. Here’s the clearest path from where you are to your next opportunity." action={<Button onClick={() => setLocation('/app/student/skill-gap')}>Explore a target role <ArrowRight size={15} /></Button>} /><div className="grid gap-4 md:grid-cols-4"><Metric label="Readiness score" value="72 / 100" detail="+8 points in the last 30 days" icon={TrendingUp} /><Metric label="Profile strength" value="78%" detail="2 signals need evidence" icon={UserRound} accent="orange" /><Metric label="Strongest match" value="91%" detail="Associate Product Analyst" icon={Target} accent="yellow" /><Metric label="Active applications" value={String(applications.length)} detail="1 interview this week" icon={BriefcaseBusiness} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.45fr_.75fr]"><Card className="p-6"><SectionHeading eyebrow="Momentum" title="Your readiness, over time" detail="A healthier signal is built one proof point at a time." action={<Badge tone="green">On track</Badge>} /><div className="h-[240px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={[{ month: 'Jun', score: 48 }, { month: 'Jul', score: 53 }, { month: 'Aug', score: 59 }, { month: 'Sep', score: 64 }, { month: 'Oct', score: 72 }]}><defs><linearGradient id="readiness" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#16877b" stopOpacity=".3" /><stop offset="100%" stopColor="#16877b" stopOpacity="0" /></linearGradient></defs><CartesianGrid vertical={false} stroke="#e8e4da" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: '#7b918d', fontSize: 11 }} /><YAxis domain={[40, 80]} axisLine={false} tickLine={false} tick={{ fill: '#7b918d', fontSize: 11 }} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #dce5dc', background: '#fffdf8', fontSize: 12 }} /><Area type="monotone" dataKey="score" stroke="#16877b" strokeWidth={3} fill="url(#readiness)" /></AreaChart></ResponsiveContainer></div></Card><Card className="p-6"><SectionHeading eyebrow="Next best moves" title="Build momentum" /><div className="space-y-5">{[['Complete SQL module','64% done','/app/student/learning',BookOpen],['Add a project outcome','2 min task','/app/student/profile',Sparkles],['Review new matches','6 opportunities','/app/student/opportunities',Compass]].map(([title, sub, href, Icon]) => { const IconComp = Icon as typeof BookOpen; return <Link href={href as string} key={title as string} className="group flex items-center gap-3"><IconBox className="bg-[#edf3ed] text-[#16877b]"><IconComp size={17} /></IconBox><div className="min-w-0 flex-1"><p className="text-sm font-bold">{title as string}</p><p className="mt-0.5 text-xs text-[#6e8580]">{sub as string}</p></div><ChevronRight size={16} className="text-[#a4b5ae] transition-transform group-hover:translate-x-1" /></Link>})}</div></Card></div><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_.9fr]"><Card className="p-6"><SectionHeading eyebrow="For you" title="Opportunities worth a look" action={<Link href="/app/student/opportunities" className="text-xs font-bold text-[#16877b]">See all <ArrowRight className="ml-1 inline" size={13} /></Link>} /><div className="space-y-3">{opportunities.slice(0, 3).map((opportunity) => <OpportunityRow key={opportunity.id} opportunity={opportunity} />)}</div></Card><Card className="overflow-hidden"><div className="bg-[#153f43] p-6 text-[#f7f4ec]"><p className="mono text-[10px] uppercase tracking-[.18em] text-[#f5c879]">This week’s insight</p><p className="display mt-4 text-2xl font-bold leading-tight">Your project evidence is now doing more work than your certifications.</p><p className="mt-4 text-sm leading-6 text-[#b6cec5]">Add one measurable outcome to CampusPulse and you could unlock 4 more product analytics roles.</p><Button variant="soft" className="mt-5 bg-[#f5c879] text-[#153f43]" onClick={() => setLocation('/app/student/profile')}>Strengthen profile</Button></div></Card></div></>; }

function OpportunityRow({ opportunity, onApply }: { opportunity: Opportunity; onApply?: () => void }) { const [, setLocation] = useLocation(); return <div className="group flex items-center gap-4 rounded-2xl border border-[#e8e4da] p-4 transition-colors hover:border-[#a9cfc2]"><div className="grid size-10 shrink-0 place-items-center rounded-xl bg-[#edf3ed] text-xs font-extrabold text-[#16877b]">{opportunity.company.slice(0, 2).toUpperCase()}</div><div className="min-w-0 flex-1"><button data-testid={`link-opportunity-${opportunity.id}`} className="text-left text-sm font-bold hover:text-[#16877b]" onClick={() => setLocation(`/app/student/opportunities/${opportunity.id}`)}>{opportunity.title}</button><p className="mt-1 text-xs text-[#6e8580]">{opportunity.company} · {opportunity.location}</p></div><div className="hidden text-right sm:block"><p className="mono text-sm font-bold text-[#16877b]">{opportunity.match}%</p><p className="text-[10px] text-[#6e8580]">match</p></div><Button variant="ghost" className="hidden sm:inline-flex" onClick={onApply ?? (() => setLocation(`/app/student/opportunities/${opportunity.id}`))}>View <ChevronRight size={15} /></Button></div>; }

function StudentProfile() { const { toast } = useDemo(); const [saved, setSaved] = useState(false); const groups = ['Technical', 'Professional']; return <><PageIntro eyebrow="My profile" title="Your competency profile" detail="A living view of the skills, proof, and context behind your next career move." action={<Button onClick={() => { setSaved(true); toast('Profile saved — your signal is up to date.', 'success'); }}> {saved ? <Check size={15} /> : <Settings size={15} />} {saved ? 'Saved' : 'Edit profile'}</Button>} /><div className="grid gap-6 xl:grid-cols-[.72fr_1.28fr]"><Card className="p-6"><div className="flex items-center gap-4"><Avatar initials={currentStudent.initials} size="lg" /><div><h2 className="display text-xl font-extrabold">{currentStudent.name}</h2><p className="mt-1 text-sm text-[#6e8580]">{currentStudent.branch} · {currentStudent.year}</p><p className="mt-2 text-xs font-bold text-[#16877b]">{currentStudent.cgpa} CGPA</p></div></div><div className="mt-8 rounded-2xl bg-[#153f43] p-5 text-[#f7f4ec]"><div className="flex justify-between"><div><p className="mono text-[10px] uppercase tracking-[.16em] text-[#9cc6b7]">Readiness</p><p className="mt-2 text-3xl font-extrabold">72<span className="text-base text-[#9cc6b7]"> / 100</span></p></div><TrendingUp className="text-[#f5c879]" /></div><Progress value={72} color="bg-[#f5c879]" /><p className="mt-3 text-xs text-[#b6cec5]">Top 18% of your cohort</p></div><div className="mt-6"><p className="mono text-[10px] font-bold uppercase tracking-[.16em] text-[#7b918d]">Proof on file</p><div className="mt-3 space-y-3">{currentStudent.projects.map((item) => <div key={item} className="flex items-start gap-3 text-sm"><span className="mt-0.5 text-[#16877b]"><CircleCheck size={16} /></span><span>{item}</span></div>)}{currentStudent.certifications.map((item) => <div key={item} className="flex items-start gap-3 text-sm"><span className="mt-0.5 text-[#c85e2b]"><CircleCheck size={16} /></span><span>{item}</span></div>)}</div></div></Card><div className="space-y-6"><Card className="p-6"><SectionHeading eyebrow="Competencies" title="Skills, with context" detail="Signals are grouped by what they help you do." /><div className="grid gap-7 md:grid-cols-2">{groups.map((group) => <div key={group}><div className="mb-4 flex items-center justify-between"><h3 className="font-bold">{group}</h3><span className="text-xs text-[#6e8580]">{currentStudent.skills.filter((s) => s.category === group).length} skills</span></div><div className="space-y-4">{currentStudent.skills.filter((s) => s.category === group).map((skill) => <div key={skill.name}><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{skill.name}</span><span className="text-xs text-[#6e8580]">{skill.level}</span></div><div className="flex items-center gap-3"><Progress value={skill.score} /><span className="mono w-7 text-right text-[11px] text-[#6e8580]">{skill.score}</span></div></div>)}</div></div>)}</div></Card><Card className="p-6"><SectionHeading eyebrow="Signal quality" title="What to improve next" /><div className="grid gap-3 md:grid-cols-3">{[['Project outcomes','Add numbers to one project','High impact','orange'],['Leadership','Show one team contribution','Medium impact','yellow'],['Machine Learning','Finish your current module','Medium impact','teal']].map(([a,b,c,t]) => <div key={a} className="rounded-2xl bg-[#f3f0e7] p-4"><span className={`inline-block size-2 rounded-full ${t === 'orange' ? 'bg-[#e98250]' : t === 'yellow' ? 'bg-[#e5b544]' : 'bg-[#16877b]'}`} /><p className="mt-3 text-sm font-bold">{a}</p><p className="mt-1 text-xs leading-5 text-[#6e8580]">{b}</p><Badge tone={t === 'orange' ? 'orange' : t === 'teal' ? 'teal' : 'neutral'}>{c}</Badge></div>)}</div></Card></div></div></>; }

function SkillGap() { const [role, setRole] = useState('Product Analyst'); const roles: Record<string, string[]> = { 'Product Analyst': ['SQL', 'Python', 'Product Thinking', 'Communication', 'Experiment Design'], 'Data Scientist': ['Python', 'Machine Learning', 'SQL', 'Statistics', 'Communication'], 'Frontend Engineer': ['React', 'JavaScript', 'Data Structures', 'Communication', 'Accessibility'] }; const gap = roleGap(currentStudent, roles[role]); return <><PageIntro eyebrow="Target role" title="Close the distance, deliberately." detail="Pick a role and see the exact signals between your current profile and a credible application." action={<select value={role} onChange={(e) => setRole(e.target.value)} className="rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-4 py-3 text-sm font-bold outline-none">{Object.keys(roles).map((item) => <option key={item}>{item}</option>)}</select>} /><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><Card className="bg-[#153f43] p-7 text-[#f7f4ec]"><p className="mono text-[10px] uppercase tracking-[.18em] text-[#f5c879]">Role signal</p><h2 className="display mt-4 text-3xl font-extrabold">{role}</h2><p className="mt-3 text-sm leading-6 text-[#b6cec5]">The strongest route from your current profile into this role.</p><div className="mt-10 flex items-end gap-3"><span className="display text-6xl font-extrabold">74</span><span className="mb-2 text-sm text-[#b6cec5]">/ 100 current fit</span></div><Progress value={74} color="bg-[#f5c879]" /><div className="mt-8 space-y-3 text-sm"><div className="flex justify-between"><span className="text-[#b6cec5]">Ready now</span><b>{gap.filter((g) => g.status === 'Ready').length} skills</b></div><div className="flex justify-between"><span className="text-[#b6cec5]">Build next</span><b>{gap.filter((g) => g.status !== 'Ready').length} skills</b></div></div></Card><Card className="p-7"><SectionHeading eyebrow="Explainable comparison" title={`Your ${role} gap`} detail="No black box. Each bar is a specific, actionable signal." /><div className="space-y-6">{gap.map((item) => <div key={item.name}><div className="mb-2 flex items-center justify-between"><div><span className="text-sm font-bold">{item.name}</span>{item.status !== 'Ready' && <Badge tone={item.status === 'Priority gap' ? 'orange' : 'neutral'}>{item.status}</Badge>}</div><span className="mono text-xs text-[#6e8580]">{item.current} → {item.target}</span></div><div className="relative h-3 overflow-hidden rounded-full bg-[#e8e4da]"><div className="absolute inset-y-0 left-0 rounded-full bg-[#d2ddd4]" style={{ width: `${item.target}%` }} /><div className={`absolute inset-y-0 left-0 rounded-full ${item.status === 'Ready' ? 'bg-[#16877b]' : 'bg-[#e98250]'}`} style={{ width: `${item.current}%` }} /></div></div>)}<div className="mt-8 rounded-2xl bg-[#e7f0e8] p-4 text-sm leading-6 text-[#456460]"><Lightbulb className="mb-2 text-[#aa7b18]" size={17} /><b>Our read:</b> SQL is already a differentiator. Spend your next 6 hours on experiment design — it’s the only priority gap for the highest-match roles.</div></div></Card></div></>; }

function Learning() { const { toast } = useDemo(); const [list, setList] = useState(modules); return <><PageIntro eyebrow="Learning plan" title="A roadmap with a reason." detail="Short, staged learning that maps directly to the roles you want — no course hoarding." action={<Badge tone="teal">12h 10m remaining</Badge>} /><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Card className="p-6"><div className="flex items-center justify-between"><div><p className="mono text-[10px] font-bold uppercase tracking-[.16em] text-[#16877b]">Your sequence</p><h2 className="display mt-2 text-2xl font-extrabold">Product analyst sprint</h2></div><span className="mono text-xs text-[#6e8580]">{list.filter((m) => m.progress > 0).length}/4 started</span></div><div className="mt-7 space-y-4">{list.map((module, index) => <div key={module.id} className="group rounded-2xl border border-[#e8e4da] p-5 transition-colors hover:border-[#a9cfc2]"><div className="flex gap-4"><div className={`grid size-10 shrink-0 place-items-center rounded-xl ${module.color === 'orange' ? 'bg-[#fce0ce] text-[#c85e2b]' : module.color === 'navy' ? 'bg-[#dbe7e6] text-[#153f43]' : module.color === 'yellow' ? 'bg-[#f8edc9] text-[#aa7b18]' : 'bg-[#d9eee7] text-[#16877b]'}`}><span className="mono text-xs font-bold">0{index + 1}</span></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold">{module.title}</h3><Badge tone={module.stage === 'Now' ? 'teal' : 'neutral'}>{module.stage}</Badge></div><p className="mt-1 text-xs text-[#6e8580]">{module.provider} · {module.duration} · builds {module.skill}</p><div className="mt-4 flex items-center gap-3"><Progress value={module.progress} color={module.progress ? 'bg-[#16877b]' : 'bg-[#b8c8bf]'} /><span className="mono text-[11px] text-[#6e8580]">{module.progress}%</span></div></div><Button variant={module.progress ? 'soft' : 'outline'} className="hidden h-9 shrink-0 px-3 text-xs sm:inline-flex" onClick={() => { setList((items) => items.map((item) => item.id === module.id ? { ...item, progress: item.progress ? Math.min(100, item.progress + 12) : 12 } : item)); toast(`${module.title} marked as in progress.`, 'success'); }}>{module.progress ? 'Continue' : 'Start'}</Button></div></div>)}</div></Card><Card className="h-fit overflow-hidden"><div className="bg-[#fce0ce] p-6"><p className="mono text-[10px] font-bold uppercase tracking-[.16em] text-[#c85e2b]">Why this order?</p><h2 className="display mt-3 text-2xl font-extrabold">Build the base, then show your thinking.</h2><p className="mt-3 text-sm leading-6 text-[#72584e]">The sprint starts with the most transferable skill, then layers the decision-making context recruiters look for.</p></div><div className="space-y-5 p-6"><div className="flex gap-3"><span className="mono text-sm font-bold text-[#e98250]">01</span><p className="text-sm leading-6"><b>SQL first</b><br /><span className="text-[#6e8580]">It already appears in 3 of your top matches.</span></p></div><div className="flex gap-3"><span className="mono text-sm font-bold text-[#e98250]">02</span><p className="text-sm leading-6"><b>Decisions next</b><br /><span className="text-[#6e8580]">Turn analysis into a product recommendation.</span></p></div><div className="flex gap-3"><span className="mono text-sm font-bold text-[#e98250]">03</span><p className="text-sm leading-6"><b>Evidence last</b><br /><span className="text-[#6e8580]">Package the work so someone can trust it.</span></p></div></div></Card></div></>; }

function Opportunities() { const [filter, setFilter] = useState('All'); const filtered = filter === 'All' ? opportunities : opportunities.filter((item) => item.type === filter); return <><PageIntro eyebrow="Opportunity radar" title="Roles with a reason to say yes." detail="Ranked against your actual signal, not just a keyword cloud." action={<div className="flex gap-2">{['All', 'Internship', 'Full-time'].map((item) => <Button key={item} variant={filter === item ? 'primary' : 'soft'} onClick={() => setFilter(item)}>{item}</Button>)}</div>} /><div className="mb-5 flex items-center justify-between text-xs text-[#6e8580]"><span><b className="text-[#153f43]">{filtered.length}</b> opportunities tuned to your profile</span><span className="flex items-center gap-1"><Filter size={14} /> Sorted by match</span></div><div className="grid gap-4 lg:grid-cols-2">{filtered.map((opportunity) => <Card key={opportunity.id} className="group p-5 transition-all hover:-translate-y-0.5 hover:border-[#a9cfc2]"><div className="flex items-start justify-between gap-4"><div className="flex gap-3"><div className="grid size-11 place-items-center rounded-xl bg-[#edf3ed] text-sm font-extrabold text-[#16877b]">{opportunity.company.slice(0, 2).toUpperCase()}</div><div><Link href={`/app/student/opportunities/${opportunity.id}`} className="font-bold hover:text-[#16877b]">{opportunity.title}</Link><p className="mt-1 text-xs text-[#6e8580]">{opportunity.company} · {opportunity.location}</p></div></div><div className="text-right"><p className="mono text-lg font-bold text-[#16877b]">{opportunity.match}%</p><p className="text-[10px] text-[#6e8580]">match</p></div></div><p className="mt-5 line-clamp-2 text-sm leading-6 text-[#617174]">{opportunity.description}</p><div className="mt-5 flex flex-wrap gap-1.5">{opportunity.skills.map((skill) => <Badge key={skill} tone={currentStudent.skills.some((s) => s.name === skill) ? 'teal' : 'neutral'}>{skill}</Badge>)}</div><div className="mt-5 flex items-center justify-between border-t border-[#eeeae0] pt-4"><span className="flex items-center gap-1 text-xs text-[#6e8580]"><Clock3 size={14} /> Apply by {opportunity.deadline}</span><Link href={`/app/student/opportunities/${opportunity.id}`} className="inline-flex items-center gap-1 text-xs font-bold text-[#16877b]">Why this match <ArrowRight size={13} /></Link></div></Card>)}</div></>; }

function OpportunityDetail() { const { id } = useParams<{ id: string }>(); const opportunity = opportunities.find((item) => item.id === id) ?? opportunities[0]; const { applications, apply, toast } = useDemo(); const applied = applications.some((item) => item.opportunityId === opportunity.id); const score = calculateMatchScore(currentStudent, opportunity); const breakdown = [['Skill match', score.skillMatch, scoreWeights.skillMatch], ['Projects', score.projectScore, scoreWeights.projects], ['Education', score.educationScore, scoreWeights.education], ['Experience', score.experienceScore, scoreWeights.experience], ['Other signals', score.otherScore, scoreWeights.other]]; return <><Link href="/app/student/opportunities" className="mb-6 inline-flex items-center gap-1 text-sm font-semibold text-[#6e8580] hover:text-[#16877b]"><ArrowRight className="rotate-180" size={15} /> Back to opportunities</Link><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><div><Card className="overflow-hidden"><div className="bg-[#153f43] p-7 text-[#f7f4ec] md:p-9"><div className="flex items-start gap-4"><div className="grid size-14 place-items-center rounded-2xl bg-[#f5c879] text-lg font-extrabold text-[#153f43]">{opportunity.company.slice(0, 2).toUpperCase()}</div><div><Badge tone="orange">{opportunity.type}</Badge><h1 className="display mt-3 text-3xl font-extrabold md:text-4xl">{opportunity.title}</h1><p className="mt-2 text-sm text-[#b6cec5]">{opportunity.company} · {opportunity.location}</p></div></div><p className="mt-8 max-w-2xl leading-7 text-[#d2e1da]">{opportunity.description}</p></div><div className="p-7 md:p-9"><div className="flex flex-wrap items-center gap-3 text-sm text-[#6e8580]"><span className="flex items-center gap-1"><Clock3 size={15} /> Deadline {opportunity.deadline}</span><span>·</span><span>{opportunity.eligibility}</span></div><h2 className="display mt-9 text-xl font-extrabold">What you’ll work on</h2><p className="mt-3 leading-7 text-[#617174]">Partner with a cross-functional team to turn customer and business signals into decisions. You’ll have room to ask better questions, test ideas, and make the result visible.</p><div className="mt-7 flex flex-wrap gap-2">{opportunity.skills.map((skill) => <Badge key={skill} tone={score.skillHits.includes(skill) ? 'teal' : 'orange'}>{skill}</Badge>)}</div></div></Card></div><div className="space-y-6"><Card className="p-6"><div className="flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.16em] text-[#16877b]">Why this match</p><p className="mt-2 display text-4xl font-extrabold">{opportunity.match}%</p></div><div className="grid size-16 place-items-center rounded-full border-[7px] border-[#16877b] border-r-[#dce5dc] text-xs font-bold text-[#16877b]">{opportunity.match}%</div></div><p className="mt-3 text-sm leading-6 text-[#6e8580]">Based on the same scoring logic recruiters use to shortlist candidates.</p><div className="mt-7 space-y-4">{breakdown.map(([label, value, weight]) => <div key={label as string}><div className="mb-1.5 flex justify-between text-xs"><span>{label as string} <span className="text-[#a4b5ae]">({weight}%)</span></span><b>{value as number}</b></div><Progress value={value as number} color={label === 'Skill match' ? 'bg-[#16877b]' : 'bg-[#9dbdb1]'} /></div>)}</div><div className="mt-7 border-t border-[#e8e4da] pt-5"><Button className="w-full" disabled={applied} onClick={() => { apply(opportunity.id); toast(applied ? 'Application already submitted.' : `Application sent to ${opportunity.company}.`, 'success'); }}>{applied ? <><Check size={16} /> Application submitted</> : <><Send size={16} /> Apply to this role</>}</Button><p className="mt-3 text-center text-[11px] text-[#6e8580]">You can update your application profile before sending.</p></div></Card><Card className="bg-[#fce0ce] p-6"><CircleAlert className="text-[#c85e2b]" size={18} /><p className="mt-3 text-sm font-bold">One thing to strengthen</p><p className="mt-2 text-sm leading-6 text-[#72584e]">Your SQL and Python signals are strong. Add an experiment result to CampusPulse to make the product-thinking case undeniable.</p><Link href="/app/student/profile" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-[#c85e2b]">Open profile <ArrowRight size={13} /></Link></Card></div></div></>; }

function Applications() { const { applications } = useDemo(); const stages = ['Applied', 'Screening', 'Interview', 'Offer'] as const; return <><PageIntro eyebrow="Application desk" title="Keep every next step in view." detail="A calm pipeline for the roles you’re actively moving through." action={<Badge tone="teal">{applications.length} active</Badge>} /><div className="grid gap-4 md:grid-cols-4">{stages.map((stage) => <Card key={stage} className="min-h-[280px] bg-[#f1eee5] p-4"><div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-bold">{stage}</h2><span className="grid size-6 place-items-center rounded-full bg-[#e3dfd4] text-xs font-bold">{applications.filter((item) => item.stage === stage).length}</span></div><div className="space-y-3">{applications.filter((item) => item.stage === stage).map((application) => { const opportunity = opportunities.find((item) => item.id === application.opportunityId)!; return <div key={application.id} className="rounded-xl border border-[#e5e1d7] bg-[#fffdf8] p-4"><p className="text-sm font-bold">{opportunity.title}</p><p className="mt-1 text-xs text-[#6e8580]">{opportunity.company}</p><div className="mt-4 flex justify-between text-[10px] text-[#8a9a94]"><span>{application.appliedAt}</span><span className="font-bold text-[#16877b]">{opportunity.match}% fit</span></div></div>})}</div></Card>)}</div><Card className="mt-6 p-6"><SectionHeading eyebrow="Application health" title="Your strongest story is getting through." detail="Keep your proof points consistent across each conversation." /><div className="grid gap-4 md:grid-cols-3"><div className="rounded-2xl bg-[#e7f0e8] p-5"><p className="text-sm font-bold">Response signal</p><p className="mt-2 display text-3xl font-extrabold">2 / 3</p><p className="mt-1 text-xs text-[#6e8580]">applications progressed</p></div><div className="rounded-2xl bg-[#fce0ce] p-5"><p className="text-sm font-bold">Interview prep</p><p className="mt-2 display text-3xl font-extrabold">4</p><p className="mt-1 text-xs text-[#6e8580]">role-specific prompts ready</p></div><div className="rounded-2xl bg-[#f8edc9] p-5"><p className="text-sm font-bold">Next deadline</p><p className="mt-2 display text-3xl font-extrabold">18 Oct</p><p className="mt-1 text-xs text-[#6e8580]">Razorpay application</p></div></div></Card></>; }

function UniversityDashboard() { const readiness = [{ name: 'Jun', value: 58 }, { name: 'Jul', value: 61 }, { name: 'Aug', value: 63 }, { name: 'Sep', value: 67 }, { name: 'Oct', value: 71 }]; return <><PageIntro eyebrow="University intelligence" title="Placement readiness, before placement season." detail="A campus-wide view of where student potential is building — and where targeted support will matter most." action={<Button variant="outline"><Filter size={15} /> 2025 cohort <ChevronDown size={14} /></Button>} /><div className="grid gap-4 md:grid-cols-4"><Metric label="Students assessed" value="2,441" detail="+184 this month" icon={Users} /><Metric label="Campus readiness" value="68%" detail="+6.4 pts since June" icon={TrendingUp} accent="orange" /><Metric label="Critical gaps" value="14" detail="skills across 5 departments" icon={CircleAlert} accent="yellow" /><Metric label="Industry alignment" value="74%" detail="of top roles covered" icon={Target} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card className="p-6"><SectionHeading eyebrow="Campus pulse" title="Readiness is moving in the right direction" detail="Average cohort score by month." /><div className="h-[245px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={readiness}><CartesianGrid vertical={false} stroke="#e8e4da" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#7b918d', fontSize: 11 }} /><YAxis domain={[50, 80]} axisLine={false} tickLine={false} tick={{ fill: '#7b918d', fontSize: 11 }} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #dce5dc', background: '#fffdf8', fontSize: 12 }} /><Area type="monotone" dataKey="value" stroke="#e98250" fill="#fce0ce" strokeWidth={3} /></AreaChart></ResponsiveContainer></div></Card><Card className="p-6"><SectionHeading eyebrow="Attention needed" title="Where to intervene" /><div className="space-y-4">{departments.slice(0, 4).map((department) => <Link href="/app/university/departments" key={department.name} className="block"><div className="mb-2 flex justify-between text-sm"><span className="font-semibold">{department.name.replace(' & Engineering', '')}</span><span className="mono text-xs text-[#c85e2b]">{department.gap}% gap</span></div><Progress value={department.readiness} color={department.readiness > 70 ? 'bg-[#16877b]' : 'bg-[#e98250]'} /></Link>)}</div></Card></div><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_1fr]"><Card className="p-6"><SectionHeading eyebrow="Demand signal" title="Top emerging skills" action={<Link href="/app/university/demand" className="text-xs font-bold text-[#16877b]">View full report <ArrowRight size={13} className="inline" /></Link>} /><div className="space-y-4">{[['Product analytics', 78, '+18%'], ['Cloud architecture', 69, '+14%'], ['Data storytelling', 63, '+11%'], ['Experiment design', 54, '+24%']].map(([skill, value, delta]) => <div key={skill as string} className="flex items-center gap-4"><span className="w-32 text-sm font-semibold">{skill as string}</span><Progress value={value as number} /><span className="mono w-10 text-right text-[10px] text-[#16877b]">{delta as string}</span></div>)}</div></Card><Card className="overflow-hidden bg-[#153f43] p-6 text-[#f7f4ec]"><p className="mono text-[10px] uppercase tracking-[.18em] text-[#f5c879]">Admin brief</p><h2 className="display mt-4 text-2xl font-extrabold">The next lift is not more content. It’s better sequencing.</h2><p className="mt-3 text-sm leading-6 text-[#b6cec5]">Students are collecting credentials faster than they’re building visible proof. Training interventions should pair a skill with a project outcome.</p><Link href="/app/university/training" className="mt-5 inline-flex items-center gap-1 text-xs font-bold text-[#f5c879]">See training priorities <ArrowRight size={13} /></Link></Card></div></>; }

function UniversitySkills() { const skillData = [{ skill: 'Python', value: 81 }, { skill: 'SQL', value: 74 }, { skill: 'React', value: 62 }, { skill: 'Cloud', value: 49 }, { skill: 'Product analytics', value: 43 }, { skill: 'Communication', value: 78 }]; return <><PageIntro eyebrow="Aggregate intelligence" title="What the campus can do today." detail="A skill inventory you can act on — sliced by department, cohort, and readiness." action={<Button variant="outline"><Filter size={15} /> All departments <ChevronDown size={14} /></Button>} /><div className="grid gap-6 xl:grid-cols-[1fr_.85fr]"><Card className="p-6"><SectionHeading eyebrow="Skill coverage" title="Core skills across 2,441 students" /><div className="h-[330px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={skillData} layout="vertical" margin={{ left: 20, right: 20 }}><CartesianGrid horizontal={false} stroke="#e8e4da" /><XAxis type="number" domain={[0, 100]} hide /><YAxis dataKey="skill" type="category" axisLine={false} tickLine={false} width={112} tick={{ fill: '#456460', fontSize: 11 }} /><Bar dataKey="value" radius={[0, 7, 7, 0]} fill="#16877b">{skillData.map((item, index) => <Cell key={item.skill} fill={index > 3 ? '#e98250' : '#16877b'} />)}</Bar></BarChart></ResponsiveContainer></div></Card><Card className="p-6"><SectionHeading eyebrow="Distribution" title="Readiness bands" /><div className="mx-auto h-[220px] max-w-[270px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{ name: 'Ready', value: 31 }, { name: 'Building', value: 45 }, { name: 'Needs support', value: 24 }]} innerRadius={62} outerRadius={88} paddingAngle={4} dataKey="value"><Cell fill="#16877b" /><Cell fill="#f5c879" /><Cell fill="#e98250" /></Pie><Tooltip /></PieChart></ResponsiveContainer></div><div className="space-y-3">{[['Ready for role', '31%', '#16877b'], ['Building signal', '45%', '#e5b544'], ['Needs support', '24%', '#e98250']].map(([label, value, color]) => <div key={label} className="flex items-center justify-between text-sm"><span className="flex items-center gap-2"><span className="size-2 rounded-full" style={{ background: color }} />{label}</span><b>{value}</b></div>)}</div></Card></div></>; }

function UniversityDepartments() { return <><PageIntro eyebrow="Department view" title="Readiness by department" detail="Find the cohorts that need a nudge, not a generic intervention." action={<Button><DownloadIcon /> Export brief</Button>} /><Card className="overflow-hidden"><div className="grid grid-cols-[1.5fr_.6fr_.8fr_.7fr] border-b border-[#e8e4da] bg-[#f3f0e7] px-5 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-[#7b918d]"><span>Department</span><span>Students</span><span>Readiness</span><span>Gap</span></div>{departments.map((department) => <Link href="/app/university/training" key={department.name} className="grid grid-cols-[1.5fr_.6fr_.8fr_.7fr] items-center border-b border-[#eeeae0] px-5 py-5 text-sm transition-colors hover:bg-[#f8f6f0]"><span className="font-bold">{department.name}</span><span className="text-[#6e8580]">{department.students}</span><span className="flex items-center gap-3"><Progress value={department.readiness} color={department.readiness > 70 ? 'bg-[#16877b]' : 'bg-[#e98250]'} /><b className="w-8 text-right">{department.readiness}%</b></span><Badge tone={department.gap > 35 ? 'orange' : 'neutral'}>{department.gap}% gap</Badge></Link>)}</Card></>; }
function DownloadIcon() { return <ArrowRight size={15} className="rotate-90" />; }

function UniversityDemand() { const demand = [{ skill: 'Product analytics', supply: 43, demand: 82 }, { skill: 'Cloud architecture', supply: 49, demand: 74 }, { skill: 'Data storytelling', supply: 56, demand: 69 }, { skill: 'Experiment design', supply: 38, demand: 67 }, { skill: 'Applied AI', supply: 31, demand: 61 }]; return <><PageIntro eyebrow="Industry signal" title="Where demand is outrunning supply." detail="Compare the capability employers are asking for with what your students can evidence." action={<Badge tone="orange">Q3 2025 signal</Badge>} /><Card className="p-6"><SectionHeading eyebrow="The gap" title="Supply vs. demand by skill" /><div className="space-y-6">{demand.map((item) => <div key={item.skill} className="grid gap-2 md:grid-cols-[160px_1fr_100px] md:items-center"><span className="text-sm font-bold">{item.skill}</span><div className="space-y-2"><div className="flex items-center gap-3"><span className="w-12 text-[10px] text-[#7b918d]">Supply</span><Progress value={item.supply} color="bg-[#9dbdb1]" /><span className="mono w-7 text-right text-[10px]">{item.supply}</span></div><div className="flex items-center gap-3"><span className="w-12 text-[10px] text-[#7b918d]">Demand</span><Progress value={item.demand} color="bg-[#e98250]" /><span className="mono w-7 text-right text-[10px]">{item.demand}</span></div></div><div className="text-right"><span className="mono text-sm font-bold text-[#c85e2b]">-{item.demand - item.supply} pts</span></div></div>)}</div></Card><Card className="mt-6 bg-[#e7f0e8] p-6"><div className="flex gap-4"><IconBox className="bg-[#153f43] text-[#f5c879]"><Lightbulb size={17} /></IconBox><div><h2 className="font-bold">The actionable read</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-[#456460]">A short applied analytics studio could address the largest combined gap across Product Analytics and Experiment Design — reaching 1,120 students in CSE and IT.</p></div></div></Card></>; }

function UniversityTraining() { const recommendations = [['Applied analytics studio', 'Product analytics + Experiment design', '1,120 students', 'High'], ['Cloud foundations lab', 'Cloud architecture + DevOps', '740 students', 'High'], ['Data storytelling clinic', 'Communication + Data storytelling', '860 students', 'Medium'], ['AI project mentorship', 'Machine Learning + Applied AI', '420 students', 'Medium']]; return <><PageIntro eyebrow="Intervention planner" title="Training priorities, ranked." detail="Turn the gap report into a focused set of interventions with a clear reach." action={<Button onClick={() => alert('Training brief queued for review.')}> <Send size={15} /> Share brief</Button>} /><div className="space-y-4">{recommendations.map(([title, skills, reach, priority], index) => <Card key={title} className="flex flex-col gap-5 p-6 md:flex-row md:items-center"><div className="grid size-12 shrink-0 place-items-center rounded-2xl bg-[#fce0ce] text-[#c85e2b]"><span className="mono text-sm font-bold">0{index + 1}</span></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="font-bold">{title}</h2><Badge tone={priority === 'High' ? 'orange' : 'neutral'}>{priority} priority</Badge></div><p className="mt-1 text-sm text-[#6e8580]">{skills}</p></div><div className="text-sm"><p className="font-bold">{reach}</p><p className="text-xs text-[#6e8580]">estimated reach</p></div><Button variant="outline" onClick={() => alert(`${title} added to planning board.`)}>Add to plan <Plus size={14} /></Button></Card>)}</div></>; }

function RecruiterDashboard() { const [, setLocation] = useLocation(); return <><PageIntro eyebrow="Recruiter workspace" title="Shortlist potential, with evidence." detail="Your open roles, candidate signal, and next best recruiting action — in one clear view." action={<Button onClick={() => setLocation('/app/recruiter/create')}><Plus size={15} /> Create opportunity</Button>} /><div className="grid gap-4 md:grid-cols-4"><Metric label="Open opportunities" value="6" detail="2 published this week" icon={BriefcaseBusiness} /><Metric label="Candidates ranked" value="384" detail="+42 new this week" icon={Users} accent="orange" /><Metric label="Shortlist quality" value="86%" detail="role-fit confidence" icon={Target} accent="yellow" /><Metric label="Time to shortlist" value="2.4d" detail="1.1d faster than last month" icon={Clock3} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_.88fr]"><Card className="p-6"><SectionHeading eyebrow="Hiring pulse" title="Your roles are attracting the right signal" /><div className="h-[230px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{ name: 'Sep 1', applicants: 42, shortlisted: 9 }, { name: 'Sep 8', applicants: 58, shortlisted: 12 }, { name: 'Sep 15', applicants: 67, shortlisted: 14 }, { name: 'Sep 22', applicants: 81, shortlisted: 19 }, { name: 'Sep 29', applicants: 96, shortlisted: 24 }]}><CartesianGrid vertical={false} stroke="#e8e4da" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#7b918d', fontSize: 10 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: '#7b918d', fontSize: 10 }} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #dce5dc', background: '#fffdf8', fontSize: 12 }} /><Bar dataKey="applicants" fill="#9dbdb1" radius={[5, 5, 0, 0]} /><Bar dataKey="shortlisted" fill="#e98250" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div><div className="mt-3 flex gap-5 text-xs text-[#6e8580]"><span className="flex items-center gap-2"><span className="size-2 rounded-full bg-[#9dbdb1]" /> Applicants</span><span className="flex items-center gap-2"><span className="size-2 rounded-full bg-[#e98250]" /> Shortlisted</span></div></Card><Card className="p-6"><SectionHeading eyebrow="Needs your eye" title="Candidate queues" /><div className="space-y-4">{[['Associate Product Analyst','128 candidates','/app/recruiter/candidates'],['Data Science Intern','74 candidates','/app/recruiter/candidates'],['Frontend Engineer Intern','56 candidates','/app/recruiter/candidates']].map(([title,count,href]) => <Link href={href} key={title} className="flex items-center gap-3 rounded-xl p-2 hover:bg-[#f3f0e7]"><IconBox className="bg-[#edf3ed] text-[#16877b]"><BriefcaseBusiness size={17} /></IconBox><div className="flex-1"><p className="text-sm font-bold">{title}</p><p className="text-xs text-[#6e8580]">{count}</p></div><ChevronRight size={15} className="text-[#a4b5ae]" /></Link>)}</div></Card></div><Card className="mt-6 overflow-hidden"><div className="flex items-center justify-between p-6"><SectionHeading eyebrow="Recent candidate signal" title="Strong matches worth opening" /><Link href="/app/recruiter/candidates" className="text-xs font-bold text-[#16877b]">View pool <ArrowRight size={13} className="inline" /></Link></div><CandidateTable compact /></Card></>; }

function RecruiterCreate() { const { toast } = useDemo(); const [published, setPublished] = useState(false); const [title, setTitle] = useState(''); const [company, setCompany] = useState('Tata Digital'); const [type, setType] = useState('Full-time'); const [skills, setSkills] = useState('SQL, Python, Product Thinking'); return <><PageIntro eyebrow="Create opportunity" title="Write a brief candidates can see themselves in." detail="A clear brief creates a better match — and a better first conversation." /><div className="grid gap-6 xl:grid-cols-[1fr_.7fr]"><Card className="p-6 md:p-8"><div className="grid gap-5 md:grid-cols-2"><label className="md:col-span-2"><span className="text-xs font-bold">Role title</span><input data-testid="input-opportunity-title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Associate Product Analyst" className="mt-2 w-full rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-4 py-3 text-sm outline-none focus:border-[#16877b]" /></label><label><span className="text-xs font-bold">Company</span><select value={company} onChange={(e) => setCompany(e.target.value)} className="mt-2 w-full rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-4 py-3 text-sm outline-none">{companyNames.map((item) => <option key={item}>{item}</option>)}</select></label><label><span className="text-xs font-bold">Role type</span><select value={type} onChange={(e) => setType(e.target.value)} className="mt-2 w-full rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-4 py-3 text-sm outline-none"><option>Full-time</option><option>Internship</option></select></label><label className="md:col-span-2"><span className="text-xs font-bold">Skills to look for</span><input value={skills} onChange={(e) => setSkills(e.target.value)} className="mt-2 w-full rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-4 py-3 text-sm outline-none focus:border-[#16877b]" /></label><label className="md:col-span-2"><span className="text-xs font-bold">What will this person work on?</span><textarea rows={5} defaultValue="Partner with product and operations teams to turn customer signals into decisions used by millions of people." className="mt-2 w-full resize-none rounded-xl border border-[#dce5dc] bg-[#fbfaf5] px-4 py-3 text-sm leading-6 outline-none focus:border-[#16877b]" /></label></div><div className="mt-6 flex justify-end gap-3"><Button variant="soft">Save draft</Button><Button disabled={!title.trim()} onClick={() => { setPublished(true); toast(`${title} is live and ready for candidates.`, 'success'); }}>Publish opportunity <Send size={15} /></Button></div></Card><Card className="h-fit overflow-hidden"><div className="bg-[#153f43] p-6 text-[#f7f4ec]"><p className="mono text-[10px] uppercase tracking-[.18em] text-[#f5c879]">Live preview</p><h2 className="display mt-5 text-2xl font-extrabold">{title || 'Your role title'}</h2><p className="mt-2 text-sm text-[#b6cec5]">{company} · Bengaluru · {type}</p><div className="mt-6 flex flex-wrap gap-1.5">{skills.split(',').map((skill) => <span key={skill} className="rounded-full bg-[#35615f] px-2.5 py-1 text-[11px] text-[#d5e6df]">{skill.trim()}</span>)}</div></div><div className="p-6"><p className="text-sm leading-6 text-[#617174]">Candidates will see your role beside a transparent match explanation, so they know where they’re strong and what to build.</p>{published && <div className="mt-5 flex items-center gap-2 rounded-xl bg-[#d9eee7] p-3 text-sm font-bold text-[#176a61]"><CircleCheck size={16} /> Published successfully</div>}</div></Card></div></>; }

function CandidateTable({ compact = false }: { compact?: boolean }) { const [, setLocation] = useLocation(); return <div className="overflow-x-auto"><div className="min-w-[620px]"><div className="grid grid-cols-[1.25fr_.7fr_1fr_.65fr] border-y border-[#eeeae0] bg-[#f3f0e7] px-6 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-[#7b918d]"><span>Candidate</span><span>Match</span><span>Top signals</span><span>Action</span></div>{candidates.slice(0, compact ? 4 : 6).map((candidate) => { const student = students.find((item) => item.id === candidate.studentId)!; return <div key={candidate.studentId} className="grid grid-cols-[1.25fr_.7fr_1fr_.65fr] items-center border-b border-[#eeeae0] px-6 py-4"><div className="flex items-center gap-3"><Avatar initials={student.initials} size="sm" /><div><p className="text-sm font-bold">{student.name}</p><p className="text-xs text-[#6e8580]">{student.branch} · {student.year}</p></div></div><span className="mono font-bold text-[#16877b]">{candidate.match}%</span><div className="flex flex-wrap gap-1">{candidate.topSkills.slice(0, 2).map((skill) => <Badge key={skill} tone="teal">{skill}</Badge>)}</div><Button variant="ghost" className="justify-self-start text-xs" onClick={() => setLocation(`/app/recruiter/candidates/${candidate.studentId}`)}>Open <ChevronRight size={14} /></Button></div>})}</div></div>; }

function RecruiterOpportunities() { return <><PageIntro eyebrow="Opportunity management" title="Your open roles." detail="Keep briefs sharp and candidate flow moving." action={<Link href="/app/recruiter/create" className="inline-flex items-center gap-2 rounded-xl bg-[#16877b] px-4 py-2.5 text-sm font-semibold text-[#f7f4ec]"><Plus size={15} /> New opportunity</Link>} /><div className="grid gap-4 md:grid-cols-2">{opportunities.slice(0, 4).map((item) => <Card key={item.id} className="p-5"><div className="flex justify-between gap-4"><div><Badge tone={item.type === 'Internship' ? 'orange' : 'teal'}>{item.type}</Badge><h2 className="mt-3 font-bold">{item.title}</h2><p className="mt-1 text-xs text-[#6e8580]">{item.company} · {item.location}</p></div><button className="rounded-lg p-2 text-[#6e8580] hover:bg-[#f3f0e7]"><Settings size={16} /></button></div><div className="mt-6 flex items-center justify-between border-t border-[#eeeae0] pt-4"><span className="text-xs text-[#6e8580]">128 candidates · posted {item.posted}</span><Link href="/app/recruiter/candidates" className="text-xs font-bold text-[#16877b]">Review candidates <ArrowRight size={13} className="inline" /></Link></div></Card>)}</div></>; }
function RecruiterCandidates() { const [query, setQuery] = useState(''); const visible = candidates.filter((item) => students.find((student) => student.id === item.studentId)?.name.toLowerCase().includes(query.toLowerCase())); return <><PageIntro eyebrow="Candidate pool" title="The shortlist, with the why." detail="Ranked recommendations grounded in evidence — not a resume keyword count." action={<div className="relative"><Search className="absolute left-3 top-3 text-[#7b918d]" size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search candidates" className="w-52 rounded-xl border border-[#dce5dc] bg-[#fbfaf5] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#16877b]" /></div>} /><Card className="overflow-hidden"><CandidateTable /></Card></>; }
function CandidateDetail() { const { id } = useParams<{ id: string }>(); const student = students.find((item) => item.id === id) ?? students[0]; const candidate = candidates.find((item) => item.studentId === student.id) ?? candidates[0]; const { toast } = useDemo(); const [shortlisted, setShortlisted] = useState(false); return <><Link href="/app/recruiter/candidates" className="mb-6 inline-flex items-center gap-1 text-sm font-semibold text-[#6e8580] hover:text-[#16877b]"><ArrowRight className="rotate-180" size={15} /> Back to candidates</Link><div className="grid gap-6 xl:grid-cols-[.82fr_1.18fr]"><Card className="p-7"><div className="flex items-center gap-4"><Avatar initials={student.initials} size="lg" /><div><h1 className="display text-2xl font-extrabold">{student.name}</h1><p className="mt-1 text-sm text-[#6e8580]">{student.branch} · {student.year}</p><p className="mt-2 text-xs font-bold text-[#16877b]">{student.cgpa} CGPA</p></div></div><div className="mt-8 rounded-2xl bg-[#153f43] p-5 text-[#f7f4ec]"><p className="mono text-[10px] uppercase tracking-[.16em] text-[#f5c879]">Role match</p><p className="mt-2 text-4xl font-extrabold">{candidate.match}%</p><p className="mt-2 text-sm text-[#b6cec5]">Strong fit for Associate Product Analyst</p></div><div className="mt-7 space-y-3"><Button className="w-full" onClick={() => { setShortlisted(true); toast(`${student.name} moved to your shortlist.`, 'success'); }}>{shortlisted ? <><Check size={16} /> Shortlisted</> : 'Shortlist candidate'}</Button><Button variant="outline" className="w-full" onClick={() => toast('Message draft opened for this candidate.', 'info')}><Send size={15} /> Start conversation</Button></div></Card><Card className="p-7"><SectionHeading eyebrow="Explainable match" title="Why this candidate is here" detail="A recruiter can see the same reasoning a student sees." /><div className="grid gap-4 md:grid-cols-2">{[['Skill alignment','91%','Python, SQL, Product Thinking'],['Proof of work','82%','2 relevant projects with outcomes'],['Education','90%',`${student.cgpa} CGPA · ${student.branch}`],['Experience','88%',student.experience[0] ?? 'Project-based experience']].map(([label, value, detail]) => <div key={label} className="rounded-2xl bg-[#f3f0e7] p-4"><div className="flex justify-between"><p className="text-sm font-bold">{label}</p><span className="mono text-sm font-bold text-[#16877b]">{value}</span></div><p className="mt-2 text-xs leading-5 text-[#6e8580]">{detail}</p></div>)}</div><div className="mt-7 border-t border-[#e8e4da] pt-6"><h3 className="font-bold">Top signals</h3><div className="mt-4 flex flex-wrap gap-2">{student.skills.map((skill) => <Badge key={skill.name} tone="teal">{skill.name} · {skill.score}</Badge>)}</div><h3 className="mt-7 font-bold">Gaps to explore</h3><div className="mt-4 flex flex-wrap gap-2">{candidate.gaps.map((gap) => <Badge key={gap} tone="orange">{gap}</Badge>)}</div></div></Card></div></>; }

function NotFound() { const [, setLocation] = useLocation(); return <div className="grid min-h-[100dvh] place-items-center bg-[#f7f4ec] p-6 text-center"><div><p className="mono text-xs font-bold uppercase tracking-[.2em] text-[#e98250]">404 · signal lost</p><h1 className="display mt-4 text-5xl font-extrabold text-[#153f43]">This page took a wrong turn.</h1><p className="mx-auto mt-4 max-w-md text-[#6e8580]">Let’s get you back to a clearer next step.</p><Button className="mt-7" onClick={() => setLocation('/')}>Return home <ArrowRight size={15} /></Button></div></div>; }

function RoutedApp() { const [location] = useLocation(); const role = location.startsWith('/app/university') ? 'university' : location.startsWith('/app/recruiter') ? 'recruiter' : 'student'; return <AppShell role={role}><Switch><Route path="/app/student/dashboard" component={StudentDashboard} /><Route path="/app/student/profile" component={StudentProfile} /><Route path="/app/student/skill-gap" component={SkillGap} /><Route path="/app/student/learning" component={Learning} /><Route path="/app/student/opportunities" component={Opportunities} /><Route path="/app/student/opportunities/:id" component={OpportunityDetail} /><Route path="/app/student/applications" component={Applications} /><Route path="/app/university/dashboard" component={UniversityDashboard} /><Route path="/app/university/skills" component={UniversitySkills} /><Route path="/app/university/departments" component={UniversityDepartments} /><Route path="/app/university/demand" component={UniversityDemand} /><Route path="/app/university/training" component={UniversityTraining} /><Route path="/app/recruiter/dashboard" component={RecruiterDashboard} /><Route path="/app/recruiter/create" component={RecruiterCreate} /><Route path="/app/recruiter/opportunities" component={RecruiterOpportunities} /><Route path="/app/recruiter/candidates" component={RecruiterCandidates} /><Route path="/app/recruiter/candidates/:id" component={CandidateDetail} /><Route component={NotFound} /></Switch></AppShell>; }

function App() { const [applications, setApplications] = useState(seedApplications); const [toast, setToast] = useState<Toast | null>(null); const apply = (opportunityId: string) => setApplications((items) => items.some((item) => item.opportunityId === opportunityId) ? items : [...items, { id: `app-${items.length + 1}`, opportunityId, stage: 'Applied', appliedAt: 'Today' }]); const notify = (message: string, tone: Toast['tone'] = 'info') => { setToast({ message, tone }); window.setTimeout(() => setToast(null), 2800); }; return <QueryClientProvider client={queryClient}><DemoContext value={{ applications, apply, toast: notify }}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Switch><Route path="/" component={Landing} /><Route path="/app/*" component={RoutedApp} /><Route component={NotFound} /></Switch></WouterRouter>{toast && <div className="fixed bottom-5 right-5 z-[100] flex max-w-sm items-center gap-3 rounded-2xl border border-[#bcd9cc] bg-[#153f43] px-4 py-3 text-sm font-semibold text-[#f7f4ec] shadow-2xl fade-up"><span className={`grid size-7 place-items-center rounded-full ${toast.tone === 'success' ? 'bg-[#f5c879] text-[#153f43]' : 'bg-[#35615f] text-[#b6cec5]'}`}>{toast.tone === 'success' ? <Check size={15} /> : <Bell size={15} />}</span>{toast.message}<button onClick={() => setToast(null)} className="ml-2 text-[#9cc6b7]"><X size={15} /></button></div>}</DemoContext></QueryClientProvider>; }

export default App;